#include <stdio.h>
#include <string.h>
#include <ctype.h>

static const char *const SYMS[13] = {
    "M",  "CM", "D",  "CD", "C",
    "XC", "L",  "XL", "X",  "IX",
    "V",  "IV", "I"
};

static const int VALUES[13] = {
    1000, 900, 500, 400, 100,
     90,   50,  40,  10,   9,
      5,    4,   1
};

int main(int argc, char *argv[])
{
    if (argc < 2) {
        puts("INVALID");
        return 0;
    }
    const char *in = argv[1];
    size_t len = strlen(in);
    if (len == 0 || len > 63) {
        puts("INVALID");
        return 0;
    }
    char upper[64];
    for (size_t i = 0; i < len; ++i) {
        char c = in[i];
        if ('a' <= c && c <= 'z') c = (char)(c - 'a' + 'A');
        upper[i] = c;
        if (c!='I' && c!='V' && c!='X' && c!='L' && c!='C' && c!='D' && c!='M') {
            puts("INVALID");
            return 0;
        }
    }
    upper[len] = '\0';
    int value = 0;
    size_t pos = 0;
    for (int i = 0; i < 13; ++i) {
        size_t sl = strlen(SYMS[i]);
        while (pos + sl <= len && strncmp(upper+pos, SYMS[i], sl) == 0) {
            value += VALUES[i];
            pos += sl;
        }
    }
    if (pos != len) { puts("INVALID"); return 0; }
    if (value > 3999) { puts("INVALID"); return 0; }
    char canonical[64];
    size_t cp = 0;
    int rem = value;
    for (int i = 0; i < 13; ++i) {
        while (rem >= VALUES[i]) {
            size_t sl = strlen(SYMS[i]);
            memcpy(canonical+cp, SYMS[i], sl);
            cp += sl;
            rem -= VALUES[i];
        }
    }
    canonical[cp] = '\0';
    if (strcmp(canonical, upper) != 0) { puts("INVALID"); return 0; }
    printf("%d\n", value);
    return 0;
}
